const TOPICS=[
 /* ================= UNIDAD 1 · TEORÍA ================= */
 {id:"so",u:1,a:"T",src:SRC.t1,t:"Concepto y propósito del sistema operativo",
  sum:"El sistema operativo es el software que actúa como intermediario entre la persona y el hardware de la computadora: maneja sus recursos y crea un ambiente en el que las aplicaciones se ejecutan de manera segura y eficiente.",
  pts:["Propósito: facilitar el uso del sistema al usuario y optimizar el uso de recursos limitados como el procesador, la memoria y los dispositivos de almacenamiento.","Sin sistema operativo, cada aplicación tendría que incluir su propio código para manejar detalles de bajo nivel del hardware, como escribir en sectores específicos del disco o manejar las interrupciones entre dispositivos.","Eso haría el software extremadamente complejo, frágil y no portable entre máquinas.","Tampoco habría protección entre programas: un error en una aplicación podría dañar la memoria de otra o dejar inutilizable la máquina.","Y sería imposible ejecutar varios programas al mismo tiempo de forma segura y eficiente."],
  ojo:"La pregunta del taller tiene dos partes: qué es y para qué sirve el SO, y qué dificultades habría sin él. Responde las dos.",
  ex:"Gracias al sistema operativo, un programa puede guardar un archivo sin saber en qué sectores del disco quedó.",
  cards:[["¿Qué es un sistema operativo?","El software intermediario entre la persona y el hardware, que maneja los recursos y crea un ambiente seguro y eficiente para las aplicaciones."],["Propósito del sistema operativo","Facilitar el uso del sistema y optimizar recursos limitados como el procesador, la memoria y el almacenamiento."],["Tres dificultades sin sistema operativo","Software complejo, frágil y no portable; sin protección entre programas; sin multitarea segura."]]},
 {id:"capas",u:1,a:"T",src:SRC.t1,t:"Hardware, software, usuario y aplicaciones",
  sum:"El hardware es la base física; el software, sobre todo el sistema operativo y su kernel, abstrae y maneja esos recursos; las aplicaciones usan los servicios del SO bajo mecanismos controlados; y el usuario interactúa con las aplicaciones o con la interfaz del SO.",
  pts:["Hardware: procesador, RAM, discos y periféricos.","Sistema operativo y kernel: intermediarios que abstraen y manejan los recursos.","Aplicaciones: programas que usan los servicios del sistema operativo.","Usuario: interactúa con las aplicaciones o con la interfaz del sistema operativo.","La separación en capas permite que cada nivel se concentre en su función sin conocer los detalles de los niveles inferiores.","El taller pide un esquema conceptual de esta relación."],
  ojo:"El ejemplo del taller con los cuatro elementos: el usuario hace clic en el ícono del navegador, el navegador pide red y pantalla al SO con llamadas al sistema, y el kernel asigna procesador y memoria y usa los controladores de la tarjeta de red y del monitor.",
  ex:"Esquema del taller: usuario → aplicaciones → sistema operativo → hardware.",
  cards:[["Orden de las capas, de abajo hacia arriba","Hardware → sistema operativo (kernel) → aplicaciones → usuario."],["¿Cómo pide una aplicación algo al hardware?","Al sistema operativo, por medio de llamadas al sistema; el kernel usa los controladores."]]},
 {id:"funciones",u:1,a:"T",src:SRC.t1,t:"Funciones principales del sistema operativo",
  sum:"El SO gestiona procesos, memoria, archivos y dispositivos de entrada y salida, ofrece una interfaz de usuario y hace la asignación general de recursos.",
  pts:["Gestión de procesos: crear, planificar y finalizar los programas en ejecución (multitarea).","Manejo de memoria: asignar y liberar espacio en RAM según cada aplicación, y recuperarlo cuando la aplicación se cierra.","Administración de archivos: creación, lectura y eliminación de documentos.","Entrada y salida: maneja los dispositivos por medio de controladores.","Interfaz de usuario: gráfica o de línea de comandos.","Asignación general de recursos: que todo el equipo funcione coordinado."],
  ojo:"El taller pide un ejemplo cotidiano por cada función. Ten uno listo para cada una.",
  ex:"Navegar mientras escuchas música (procesos); abrir un juego pesado (memoria); guardar un archivo de texto en una carpeta (archivos); conectar una impresora (E/S); doble clic en un ícono o escribir un comando (interfaz); videollamada mientras descargas un archivo (recursos).",
  cards:[["Ejemplo de gestión de procesos","Navegar en internet mientras escuchas música: el SO distribuye el tiempo de procesamiento."],["Ejemplo de manejo de memoria","Al abrir un juego pesado el SO le asigna buena parte de la RAM; al cerrarlo, esa memoria queda libre."],["Ejemplo de interfaz de usuario","Doble clic en un ícono (gráfica) o escribir un comando en la terminal (línea de comandos)."]]},
 {id:"recursos",u:1,a:"T",src:SRC.t1,t:"El SO como administrador de recursos",
  sum:"Ser administrador de recursos significa que el SO controla, asigna y libera los elementos limitados del computador para que varios programas se ejecuten de manera simultánea, justa y eficiente.",
  pts:["Recursos: tiempo de procesamiento, memoria RAM, espacio en disco y dispositivos periféricos.","Multiplexación: compartir un solo recurso físico entre muchos programas.","En el tiempo: alternando el uso de la CPU. En el espacio: dividiendo la memoria y el almacenamiento.","Lleva el seguimiento del uso y recupera los recursos cuando un proceso termina.","Arbitra los conflictos con algoritmos de planificación y colas de espera."],
  ojo:"Ejemplo de competencia por recursos del taller: dos aplicaciones intentan imprimir al mismo tiempo y el SO encola las peticiones y las atiende en orden de llegada.",
  ex:"Varios procesos compiten por el procesador y el planificador les asigna turnos cortos, dando la ilusión de que se ejecutan al mismo tiempo.",
  cards:[["Multiplexación en el tiempo vs en el espacio","Tiempo: alternar el uso de la CPU. Espacio: dividir la memoria y el almacenamiento."],["Ejemplo de competencia por recursos","Dos aplicaciones imprimen a la vez: el SO encola las peticiones en orden de llegada."]]},
 {id:"procesos",u:1,a:"T",src:SRC.t1,t:"Procesador, procesos y planificación de la CPU",
  sum:"La CPU o procesador es el hardware que ejecuta las instrucciones. Un proceso es una instancia de un programa en ejecución, con su código, datos, estado y recursos. El planificador de CPU decide qué proceso recibe el procesador y por cuánto tiempo.",
  pts:["El SO organiza la ejecución de varios procesos en la memoria principal y alterna entre ellos para aprovechar los recursos.","Mantiene una lista de procesos listos y usa el planificador de CPU para repartir el procesador.","Aplica políticas de prioridades o la técnica Round-Robin, en la que cada proceso tiene una porción de tiempo equitativa.","Gracias a la planificación, el usuario percibe que varias aplicaciones corren al mismo tiempo, aunque el procesador cambie rápidamente entre ellas.","Si el SO no administra bien los procesos: un programa puede monopolizar el procesador, todo se pone lento o deja de responder, otras aplicaciones tienen más latencia, puede haber pérdida de datos y hasta fallar el equipo."],
  ojo:"En Round-Robin la porción de tiempo es de cada PROCESO, no de cada algoritmo.",
  ex:"Abres varias aplicaciones y todas parecen responder a la vez porque el procesador cambia entre ellas muy rápido.",
  cards:[["¿Qué es un proceso?","Una instancia de un programa en ejecución, con su código, datos, estado y recursos."],["¿Qué hace el planificador de CPU?","Decide qué proceso recibe el procesador y por cuánto tiempo."],["Round-Robin","Cada proceso recibe una porción de tiempo equitativa del procesador."],["Consecuencias de no administrar bien los procesos","Un programa monopoliza la CPU, lentitud o bloqueos, más latencia, pérdida de datos o fallo del equipo."]]},
 {id:"memoria",u:1,a:"T",src:SRC.t1,t:"Memoria RAM y almacenamiento permanente",
  sum:"La RAM es memoria volátil y de acceso rápido donde se cargan los programas y datos en uso. Es el espacio de trabajo activo del sistema: sin suficiente RAM, las aplicaciones se ralentizan.",
  pts:["El SO asigna bloques de memoria a cada proceso, evita que se interfieran entre sí y libera el espacio cuando ya no se necesita.","Cuando la RAM no alcanza, usa memoria virtual: parte del disco duro o SSD como si fuera RAM.","RAM: volátil (pierde su contenido al apagar), diseñada para el acceso rápido durante la ejecución.","Almacenamiento permanente (SSD o disco duro): no volátil, de mayor capacidad y más lento.","El almacenamiento guarda el sistema operativo, las aplicaciones instaladas y los archivos del usuario."],
  ojo:"La memoria virtual vive en el disco, que es mucho más lento que la RAM. Por eso un equipo que la usa todo el tiempo se pone lento.",
  ex:"Al apagar el equipo se pierde lo que estaba en RAM, pero no los archivos guardados en el SSD.",
  cards:[["Memoria RAM","Volátil y rápida; guarda los programas y datos en uso. Es el espacio de trabajo activo."],["Memoria virtual","Usar parte del disco o SSD como si fuera RAM cuando esta no alcanza."],["RAM vs almacenamiento","RAM: volátil, rápida. SSD o disco: no volátil, más capacidad, más lento; guarda el SO, las apps y los archivos."]]},
 {id:"es",u:1,a:"T",src:SRC.t1,t:"Dispositivos de entrada y salida y controladores",
  sum:"El SO maneja teclados, mouses, impresoras, memorias USB y cámaras mediante una capa de controladores y un subsistema de E/S que organiza y coordina las peticiones entre las aplicaciones y los dispositivos.",
  pts:["Controlador (driver): módulo de software que permite al kernel comunicarse con el hardware específico de cada dispositivo.","El controlador traduce las operaciones abstractas del sistema en instrucciones concretas que el dispositivo entiende.","Subsistema de E/S: recibe las solicitudes, las ordena, las pasa al controlador correcto y avisa cuando terminan.","El controlador conoce un dispositivo; el subsistema de E/S coordina todos.","Problemas de un controlador incompatible o con errores: dispositivo no reconocido, fallos intermitentes, inestabilidad del sistema, pantallas de error y conflictos en la asignación de recursos."],
  ojo:"Por eso es esencial instalar y mantener controladores actualizados y compatibles con la versión del sistema operativo.",
  ex:"Al conectar una impresora, el SO usa su controlador para poder enviarle los documentos.",
  cards:[["¿Qué es un controlador (driver)?","Software que permite al kernel comunicarse con un dispositivo, traduciendo operaciones abstractas en instrucciones concretas."],["Controlador vs subsistema de E/S","El controlador conoce un dispositivo; el subsistema de E/S coordina las peticiones de todos."],["Problemas de un controlador incompatible","No reconoce el dispositivo, fallos intermitentes, inestabilidad, pantallas de error y conflictos de recursos."]]},
 {id:"archivos",u:1,a:"T",src:SRC.t1,t:"Archivos, directorios, permisos y sistemas de archivos",
  sum:"Un archivo es una unidad de almacenamiento con nombre, atributos y contenido. Un directorio o carpeta organiza archivos y otras carpetas de forma jerárquica. El SO maneja todo esto por medio del sistema de archivos.",
  pts:["El SO permite crear, organizar, leer, modificar y eliminar archivos y carpetas, manteniendo la consistencia e integridad de la información.","Permisos de acceso: controlan qué usuarios o procesos pueden leer, escribir, eliminar o ejecutar un archivo, y protegen la información sensible.","Sistema de archivos: define cómo se organiza la información en el almacenamiento y lleva el registro; influye en la eficiencia, la recuperación ante fallos y la seguridad.","Ejemplos: NTFS (Windows), ext4 (Linux) y APFS (Mac)."],
  ojo:"El taller pide además explicar la importancia de los permisos y de los sistemas de archivos, no solo definir archivo y carpeta.",
  ex:"Un usuario sin permiso de escritura puede abrir un archivo pero no modificarlo.",
  cards:[["Archivo vs directorio","Archivo: nombre, atributos y contenido. Directorio: organiza archivos y carpetas de forma jerárquica."],["Permisos de acceso","Controlan quién puede leer, escribir, eliminar o ejecutar un archivo."],["Sistemas de archivos por SO","NTFS: Windows. ext4: Linux. APFS: Mac."]]},
 {id:"kernel",u:1,a:"T",src:SRC.t1,t:"Kernel, controladores y llamadas al sistema",
  sum:"El kernel es la parte central del SO: corre en modo privilegiado y maneja el procesador, la memoria y los dispositivos. Una llamada al sistema es el mecanismo controlado con el que una aplicación en modo usuario pide un servicio al kernel; es la única forma segura de acceder a recursos protegidos.",
  pts:["Controlador: módulo de software que permite al kernel comunicarse con una pieza específica de hardware.","Lectura de un archivo: la aplicación hace una llamada al sistema (por ejemplo, read()), el kernel valida permisos y argumentos, usa el sistema de archivos y el controlador para acceder al almacenamiento, y devuelve los datos a la aplicación.","El taller pide representarlo con un diagrama secuencial.","Componentes del diagrama: Aplicación, Kernel, Sistema de archivos, Controlador y Disco."],
  ojo:"Diagrama secuencial: 1. read() → 2. el kernel valida permisos → 3. busca los bloques → 4. pide la lectura → 5. comandos al disco → 6. datos listos → 7, 8 y 9. los datos regresan hasta la aplicación.",
  ex:"Las aplicaciones están en modo usuario; el kernel y el sistema de archivos trabajan dentro del kernel; el disco es hardware.",
  cards:[["¿Qué es el kernel?","La parte central del SO; corre en modo privilegiado y maneja el procesador, la memoria y los dispositivos."],["¿Qué es una llamada al sistema?","El mecanismo controlado con el que una aplicación en modo usuario pide un servicio al kernel."],["Componentes del diagrama secuencial","Aplicación, Kernel, Sistema de archivos, Controlador y Disco."]]},
 {id:"shell",u:1,a:"T",src:SRC.t1,t:"Consola, shell y comandos básicos",
  sum:"La consola o terminal es una interfaz, física o emulada, para escribir comandos de texto y ver las respuestas del sistema. El shell es el programa que lee, interpreta y ejecuta esos comandos, como intermediario entre el usuario y el kernel.",
  pts:["Ejemplos de shell: Bash (Linux) y PowerShell (Windows).","GUI: íconos, ventanas y mouse; más intuitiva para quien empieza.","CLI: comandos de texto; más precisa, más eficiente en tareas repetitivas, permite automatizar con scripts y consume menos recursos.","pwd: muestra la carpeta actual en forma de ruta.","ls [opciones] [ruta]: lista el contenido de una carpeta.","cd [ruta]: permite moverse entre carpetas.","mkdir [nombre]: crea carpetas.","cp [origen] [destino]: copia archivos y carpetas."],
  ojo:"Ejemplos del taller: estando en home/documents/, se entra a spanish con cd spanish; mkdir Alejandro crea esa carpeta; cp file.txt copy.txt crea una copia con otro nombre.",
  ex:"pwd devuelve, por ejemplo, /home/documents/spanish, para confirmar dónde estás antes de otra acción.",
  cards:[["Terminal vs shell","Terminal: la interfaz donde escribes. Shell: el programa que interpreta y ejecuta los comandos."],["pwd, ls, cd, mkdir y cp","Carpeta actual, listar contenido, moverse entre carpetas, crear carpetas y copiar."],["Ventajas de la CLI","Precisión, eficiencia en tareas repetitivas, automatización con scripts y menos recursos."]]},

 /* ================= UNIDAD 1 · PRÁCTICA ================= */
 {id:"diag",u:1,a:"P",src:SRC.p1,t:"Diagnóstico: equipo lento en Soluciones Digitales",
  sum:"Un empleado administrativo reporta lentitud y bloqueos al usar a la vez un navegador con varias pestañas, una hoja de cálculo, un programa de facturación y una videoconferencia.",
  pts:["Síntomas: el uso del procesador sube mucho, la RAM está casi llena, hay procesos en segundo plano aunque se cerraron las ventanas, aparecen advertencias de falta de recursos y el usuario no sabe identificar qué procesos consumen más.","Causa 1: RAM insuficiente para la carga; el equipo usa memoria virtual (el disco), mucho más lenta.","Causa 2: demasiados procesos listos para que el planificador reparta el tiempo de forma justa.","Causa 3: procesos acumulados en segundo plano que el usuario no necesita.","Causa 4: una aplicación que usa más recursos de los que debería.","Causa 5: falta de mantenimiento, con aplicaciones innecesarias que inician solas.","Funciones del SO relacionadas: administración de recursos, procesos y planificación, memoria RAM y virtual, y el kernel como intermediario."],
  ojo:"Cerrar una ventana no siempre termina el proceso: muchas aplicaciones dejan procesos en segundo plano que el kernel sigue planificando y que siguen consumiendo CPU y memoria.",
  ex:"Análisis de conceptos: el SO es el árbitro de los recursos escasos; el planificador sobrecargado alarga las esperas; cuando la RAM se acerca al 100 % el SO mueve páginas al disco; y el kernel lucha por manejar un sistema sobrecargado.",
  cards:[["Causa principal de los bloqueos del caso","La RAM no alcanza y el SO usa memoria virtual en el disco, que es mucho más lenta."],["¿Por qué siguen procesos tras cerrar ventanas?","Muchas aplicaciones dejan procesos en segundo plano que el kernel sigue planificando."],["Funciones del SO en el caso","Administración de recursos, procesos y planificación, memoria RAM y virtual, y kernel."]]},
 {id:"herr",u:1,a:"P",src:SRC.p1,t:"Procedimiento de diagnóstico con el Administrador de tareas",
  sum:"El procedimiento del taller usa el Administrador de tareas de Windows (o el Monitor del sistema de Linux) para medir el consumo, encontrar los procesos que más gastan y revisar lo que corre en segundo plano.",
  pts:["Abrir el Administrador de tareas desde el buscador o con Ctrl + Shift + Esc.","Pestaña Rendimiento: gráficas en tiempo real de CPU y memoria; valores altos indican sobrecarga.","Pestaña Procesos: clic en Memoria o en CPU para ordenar de mayor a menor; se hace con ambas.","Expandir las aplicaciones agrupadas (por ejemplo, las pestañas del navegador) para ver sus subprocesos.","Buscar procesos de aplicaciones ya cerradas y revisar la pestaña Aplicaciones de arranque.","Antes de cambiar algo, recopilar: uso total de RAM, tamaño y uso de la memoria virtual, los 10 procesos que más consumen CPU y memoria, si hay aplicaciones críticas entre ellos y capturas del Administrador de tareas."],
  ojo:"La información se recopila antes de hacer cambios para poder comparar después y saber si las acciones funcionaron.",
  ex:"En la imagen del caso se ven 10 pestañas de Chrome; al expandirlas aparecen sus subprocesos.",
  cards:[["Atajo del Administrador de tareas","Ctrl + Shift + Esc."],["¿Dónde ver gráficas de CPU y RAM?","Pestaña Rendimiento del Administrador de tareas."],["¿Qué recopilar antes de hacer cambios?","Uso de RAM, memoria virtual, los 10 procesos que más consumen, aplicaciones críticas y capturas."]]},
 {id:"sol",u:1,a:"P",src:SRC.p1,t:"Propuesta de solución: cinco acciones",
  sum:"Cada acción indica el problema que resuelve, el procedimiento, el concepto del SO que la fundamenta y el resultado esperado, con una forma de comprobarlo.",
  pts:["1. Cerrar procesos innecesarios en segundo plano → manejo de procesos y recuperación de recursos: el kernel libera su memoria y lo saca de la cola de espera.","2. Limitar las pestañas del navegador y revisar las extensiones → manejo de memoria.","3. Deshabilitar aplicaciones de arranque innecesarias → planificación y creación de procesos: menos procesos al inicio.","4. Revisar la memoria virtual y aumentar la RAM física → administración de memoria: con más RAM, el kernel mueve menos páginas al disco.","5. Enseñar al usuario a monitorear los recursos → gestión de procesos e interfaz de usuario."],
  ojo:"“Finalizar tarea” solo en procesos que el usuario reconozca como no útiles en ese momento.",
  ex:"Memoria virtual: Configuración avanzada del sistema → Rendimiento → Configuración → Opciones avanzadas → Memoria virtual, con la opción de administrar automáticamente el tamaño del archivo de paginación y, idealmente, en un SSD.",
  cards:[["Partes de cada acción de solución","Problema, procedimiento, concepto del SO y resultado esperado (con su comprobación)."],["Concepto detrás de aumentar la RAM","Administración de memoria: con más RAM, el kernel mueve menos páginas al disco."],["¿Cómo se comprueba una acción?","Comparando el Administrador de tareas con las capturas tomadas antes de los cambios."]]},
 {id:"prev",u:1,a:"P",src:SRC.p1,t:"Plan de mejoramiento preventivo",
  sum:"El taller pide al menos cinco acciones preventivas: actualización controlada de controladores, gestión de permisos, copias de seguridad, mantenimiento de dispositivos y monitoreo de errores.",
  pts:["Actualización controlada: controladores y Windows solo desde Windows Update o la página oficial del fabricante, con un punto de restauración antes; si un controlador falla, revertirlo desde el Administrador de dispositivos.","Gestión de permisos: cuenta de usuario estándar para el trabajo diario, para no instalar programas sin autorización de soporte.","Copias de seguridad automáticas de facturas y hojas de cálculo (OneDrive o disco externo), mínimo una vez por semana, probando de vez en cuando que se pueden restaurar.","Mantenimiento: revisar cada mes el espacio libre del disco (la memoria virtual lo necesita), con el Sensor de almacenamiento o la Liberación de espacio en disco, borrando solo temporales; limpiar el polvo de los ventiladores.","Monitoreo: revisar cada mes el Visor de eventos (Registros de Windows → Sistema y Aplicación) y el Monitor de confiabilidad, y comparar con los datos del diagnóstico."],
  ojo:"El taller prohíbe ejecutar comandos que eliminen información o modifiquen configuraciones críticas sin autorización.",
  ex:"Si el procesador se calienta demasiado por el polvo, baja su velocidad para protegerse y la pc se vuelve más lenta.",
  cards:[["Cinco aspectos del plan preventivo","Controladores, permisos, copias de seguridad, mantenimiento y monitoreo de errores."],["¿Para qué el punto de restauración?","Para volver atrás si una actualización importante o un controlador nuevo da problemas."],["¿Por qué una cuenta estándar?","Para que el usuario no instale programas sin autorización de soporte."]]},
 {id:"tg1",u:1,a:"P",src:SRC.pp,t:"Parcial práctico: diagnóstico e inspección de recursos",
  sum:"TecnoGestión S.A.S. usa un equipo para facturas, archivos compartidos y reuniones virtuales. El parcial pide diferenciar síntoma, causa probable y evidencia, y relacionar el caso con las funciones del SO.",
  pts:["Funciones que intervienen: administración de procesos, planificación del procesador, gestión de memoria, sistema de archivos y administración de dispositivos.","Síntoma 1, picos de CPU: demasiados procesos compitiendo (el sistema pasa más tiempo cambiando de proceso que trabajando) y procesos en segundo plano innecesarios.","Síntoma 2, RAM casi llena: RAM insuficiente para la carga (uso de memoria virtual) y aplicaciones que dejan procesos tras cerrar sus ventanas.","Síntoma 3, poco almacenamiento: temporales, descargas antiguas, programas sin uso y caché acumulados, y una memoria virtual que crece.","Síntoma 4, impresora no disponible: el servicio de cola de impresión no inició o la cola está atorada, o el controlador está desactualizado, corrupto o incompatible.","Inspección: Administrador de tareas (Rendimiento, Procesos ordenados por CPU y memoria, Aplicaciones de arranque) y Monitor de recursos.","Datos a registrar: los 10 procesos que más usan CPU y memoria, la memoria total en uso y el espacio libre de almacenamiento."],
  ojo:"Evidencia de ejemplo: alta demanda de memoria combinada con alto uso del disco indica que el sistema está paginando al límite.",
  ex:"Comandos en PowerShell del parcial: tasklist /svc (procesos y sus servicios) y Get-CimInstance -ClassName Win32_LogicalDisk | Where-Object -Property DriveType -EQ -Value 3 (espacio disponible en los discos).",
  cards:[["Síntoma, causa y evidencia","Síntoma: lo que se observa. Causa: el origen probable. Evidencia: el dato que confirma la causa."],["Funciones del SO en el parcial","Procesos, planificación del procesador, memoria, sistema de archivos y administración de dispositivos."],["tasklist /svc","Lista los procesos y los servicios asociados."],["Evidencia de paginación al límite","Alta demanda de memoria combinada con alto uso del disco."]]},
 {id:"tg2",u:1,a:"P",src:SRC.pp,t:"Parcial práctico: impresora, plan de solución y prevención",
  sum:"Para la impresora no disponible se comprueba de lo más seguro a lo que requiere autorización. Cada acción del plan lleva: problema, procedimiento, componente del SO, riesgo o precaución y prueba.",
  pts:["Comprobaciones: 1) que la impresora esté conectada y encendida; 2) si aparece con error en el Administrador de dispositivos; 3) vaciar los trabajos atascados de la cola; 4) reiniciar el servicio de cola de impresión en services.msc; 5) reiniciar y probar; 6) con autorización, reinstalar el controlador.","Controlador: permite al SO comunicarse con el hardware de la impresora. El SO maneja las colas de impresión. El servicio de cola de impresión maneja la comunicación con el dispositivo. Si cualquiera falla, la impresora sale no disponible aunque esté bien conectada.","Acción 1: finalizar procesos en segundo plano innecesarios (procesos y memoria).","Acción 2: deshabilitar aplicaciones de arranque (creación de procesos y planificador).","Acción 3: liberar almacenamiento desde Configuración → Almacenamiento (sistema de archivos y memoria virtual).","Acción 4: vaciar la cola y reiniciar el servicio (administración de dispositivos y subsistema de impresión).","Acción 5: revisar actualizaciones del controlador en el Administrador de dispositivos (kernel y controladores).","El parcial pide al menos una medida de procesos o memoria, otra de dispositivos o controladores, y no proponer ampliar hardware como única respuesta."],
  ojo:"Riesgos: finalizar un proceso equivocado puede perder trabajo sin guardar; borrar archivos sin aprobación del usuario; cancelar la cola elimina los trabajos pendientes (avisar antes); instalar un controlador incorrecto puede dejar inútil la impresora.",
  ex:"Prevención con responsable y periodicidad: revisar aplicaciones de arranque cada mes (técnico), registro de incidentes, copias semanales de facturas (técnico), actualizaciones controladas fuera del horario laboral, y revisar almacenamiento e impresora cada semana (usuario y técnico).",
  cards:[["Orden de las comprobaciones de la impresora","De lo más seguro (conexión, cola, servicio) a lo que requiere autorización (reinstalar el controlador)."],["¿Dónde se reinicia el servicio de impresión?","En services.msc."],["Cinco partes de cada acción del parcial","Problema, procedimiento, componente del SO, riesgo o precaución y prueba."],["Riesgo de vaciar la cola de impresión","Se cancelan los trabajos pendientes: hay que avisar al usuario."]]},

 /* ================= UNIDAD 2 · TEORÍA ================= */
 {id:"procesos2",u:2,a:"T",src:SRC.t2,t:"Programa, proceso y bloque de control de procesos",
  sum:"Un programa es un conjunto de instrucciones guardado en el disco; no usa CPU ni memoria hasta que se carga. Un proceso es una instancia de un programa que se está ejecutando; el SO lo crea al iniciar el programa y le asigna tiempo de CPU y memoria.",
  pts:["El SO guarda la información de cada proceso en el bloque de control de procesos: estado, contador del proceso, registros y límites de memoria.","Un mismo programa puede generar varios procesos.","Si el SO no diferenciara programa y proceso, no podría correr varias tareas a la vez ni proteger una aplicación de otra.","Con varios programas abiertos, el sistema crea un proceso para cada uno; el kernel los planifica y parecen correr a la vez.","Administrar el procesador es necesario porque la CPU solo ejecuta una instrucción por núcleo a la vez.","Sin control de procesos: el sistema puede congelarse, las aplicaciones cerrarse de forma inesperada o la pc volverse inutilizable."],
  ojo:"La afirmación del taller “un proceso y un programa son lo mismo” es incorrecta: están relacionados, pero no son lo mismo.",
  ex:"Navegador, editor de texto, reproductor y programa de cálculo abiertos: cuatro procesos que el kernel planifica.",
  cards:[["Programa vs proceso","Programa: instrucciones en el disco, sin recursos. Proceso: el programa en ejecución, con CPU y memoria."],["¿Qué guarda el bloque de control de procesos?","Estado, contador del proceso, registros y límites de memoria."],["¿Por qué administrar el procesador?","Porque la CPU solo ejecuta una instrucción por núcleo a la vez."]]},
 {id:"estados",u:2,a:"T",src:SRC.t2,t:"Estados de un proceso y transiciones",
  sum:"Los estados principales de un proceso son: nuevo, listo, en ejecución, en espera (bloqueado) y terminado. Cada transición la provoca un evento controlado por el sistema operativo.",
  pts:["Nuevo: el proceso es creado.","Listo: se carga en memoria y espera tiempo de CPU.","En ejecución: el planificador le asigna el procesador.","En espera: necesita otro evento, por ejemplo leer un archivo o esperar el teclado.","Cuando el evento termina, vuelve a listo.","Terminado: el proceso terminó su trabajo."],
  ojo:"Después de “en espera”, el proceso vuelve a listo, no directo a ejecución.",
  ex:"Editor de texto: nuevo → listo al abrirlo; listo → en ejecución cuando recibe CPU; en ejecución → en espera mientras espera el teclado; al presionar una tecla pasa a listo y luego a ejecución; al cerrarlo, terminado.",
  cards:[["Cinco estados de un proceso","Nuevo, listo, en ejecución, en espera (bloqueado) y terminado."],["¿Cuándo pasa de listo a ejecución?","Cuando el planificador le asigna el procesador."],["¿Cuándo pasa a en espera?","Cuando necesita un evento, como leer un archivo o esperar el teclado."]]},
 {id:"planificacion",u:2,a:"T",src:SRC.t2,t:"Algoritmos de planificación: FCFS y SJF",
  sum:"Un algoritmo de planificación decide el orden y el tiempo que recibe cada proceso. Sin un criterio, algunos procesos esperarían indefinidamente mientras otros acaparan el procesador.",
  pts:["Sin orden: un proceso largo bloquea la CPU, los cortos esperan innecesariamente y baja la eficiencia del servidor.","FCFS (First Come, First Served): ejecuta los procesos en el orden en que llegan; es simple y no necesita conocer mucho de los procesos.","SJF (Shortest Job First): ejecuta primero los que necesitan menos tiempo de CPU; normalmente reduce el tiempo de espera promedio.","FCFS conviene a un sistema que recibe procesos en orden de llegada y quiere una ejecución sencilla.","SJF conviene cuando hay que priorizar los procesos que requieren menos CPU.","Desventaja de FCFS: los procesos largos hacen esperar de más a los cortos.","Desventaja de SJF: los procesos largos pueden quedarse esperando si no paran de llegar procesos pequeños."],
  ojo:"El caso del taller: un servidor con cinco procesos de distinta duración. Sin algoritmo, algunos esperan indefinidamente.",
  ex:"Si en un servidor llegan muchas tareas cortas y una muy larga, SJF termina primero las cortas; FCFS las atendería por orden de llegada.",
  cards:[["FCFS","Primero en llegar, primero en ser atendido. Simple; los largos hacen esperar a los cortos."],["SJF","El trabajo más corto primero. Reduce la espera promedio; los largos pueden quedarse esperando."],["¿Por qué un algoritmo de planificación?","Para decidir orden y tiempo de cada proceso y evitar esperas indefinidas."]]},
 {id:"concurrencia",u:2,a:"T",src:SRC.t2,t:"Condición de carrera y sección crítica",
  sum:"Una condición de carrera ocurre cuando el resultado final depende del tiempo de las operaciones. Una sección crítica es la parte del código donde un proceso accede a un recurso compartido y que no puede ejecutar más de un proceso a la vez.",
  pts:["Dos procesos modifican el mismo archivo sin coordinación: el contenido puede quedar inconsistente, uno sobrescribe los cambios del otro o ambos leen una versión antigua.","Los mecanismos de sincronización garantizan que solo un proceso modifique la sección crítica a la vez; sin ellos se pierde la integridad de los datos.","Saldo bancario: ambas operaciones leen el mismo saldo inicial, calculan por separado y escriben su resultado; puede perderse una actualización.","Leer, modificar y escribir deben ejecutarse de forma atómica.","El SO debe controlar el acceso a las secciones críticas para evitar datos dañados o inconsistentes."],
  ojo:"Saldo de 100 y dos depósitos de 50: lo correcto es 200. Con la condición de carrera, los dos leen 100, cada uno calcula 150 y el último en escribir deja 150.",
  ex:"Ejemplo distinto al banco: dos procesos actualizan el inventario de un almacén; si ambos leen la cantidad, restan uno y escriben a la vez, el inventario queda mal. Con un bloqueo, solo uno modifica el contador a la vez.",
  cards:[["Condición de carrera","El resultado final depende del tiempo de las operaciones sobre un dato compartido."],["Sección crítica","Parte del código que accede a un recurso compartido; solo un proceso puede ejecutarla a la vez."],["Saldo 100 y dos depósitos de 50 sin control","Lo correcto es 200; con la carrera puede quedar en 150."]]},
 {id:"semaforos",u:2,a:"T",src:SRC.t2,t:"Semáforos",
  sum:"Un semáforo es una herramienta de sincronización que usa un contador entero y dos operaciones: espera (wait) y señal (signal).",
  pts:["Para entrar a la sección crítica, el proceso hace espera: si el contador es mayor que cero, lo disminuye y continúa; si es cero, el proceso se bloquea.","Al salir, hace señal: aumenta el contador y puede despertar a un proceso que estaba esperando.","Semáforo binario: solo vale 0 o 1 y funciona como un bloqueo; sirve para exclusión mutua.","Semáforo contador: puede tener valores mayores que 1; se usa cuando varios procesos pueden usar a la vez un recurso limitado.","Ejemplo binario: proteger un archivo compartido. Ejemplo contador: permitir máximo tres usuarios conectados a una base de datos."],
  ojo:"El semáforo contador arranca en la cantidad de accesos permitidos: con un máximo de tres usuarios, empieza en 3.",
  ex:"Uso correcto: espera (wait) → sección crítica → señal (signal).",
  cards:[["Operación espera (wait)","Si el contador es mayor que cero, lo disminuye y continúa; si es cero, el proceso se bloquea."],["Operación señal (signal)","Aumenta el contador y puede despertar a un proceso que esperaba."],["Semáforo binario vs contador","Binario: 0 o 1, exclusión mutua. Contador: valores mayores que 1, recurso limitado compartido."]]},
 {id:"bloqueos",u:2,a:"T",src:SRC.t2,t:"Bloqueos (deadlock) y sincronización",
  sum:"Cuando varios procesos esperan indefinidamente por recursos que tienen otros, se produce un bloqueo (deadlock). Los bloqueos frecuentes suelen venir de una mala sincronización.",
  pts:["Suele pasar cuando los procesos toman los bloqueos en distinto orden.","También cuando un proceso retiene un recurso mientras espera otro.","Medida 1: tomar siempre los bloqueos en el mismo orden en todos los procesos.","Medida 2: usar tiempos de espera, para que un proceso libere sus recursos si no obtiene el segundo en un tiempo determinado.","Estas técnicas reducen la probabilidad de espera circular y mejoran la estabilidad del sistema."],
  ojo:"El taller pide dos medidas de prevención: mismo orden de bloqueos y tiempos de espera.",
  ex:"P1 tiene el archivo A y espera el B; P2 tiene el B y espera el A: ninguno avanza. Si ambos piden siempre A y luego B, no se forma la espera circular.",
  cards:[["¿Qué es un bloqueo (deadlock)?","Varios procesos esperan indefinidamente recursos que tienen otros."],["Dos medidas de prevención","Tomar los bloqueos siempre en el mismo orden y usar tiempos de espera."],["¿Qué reducen esas medidas?","La probabilidad de espera circular."]]},

 /* ================= UNIDAD 2 · PRÁCTICA (hardware y recursos) ================= */
 {id:"hilos",u:2,a:"P",src:SRC.p2,t:"Procesador multinúcleo, procesos e hilos",
  sum:"Tener un procesador de 8 núcleos y 16 hilos no garantiza que todas las aplicaciones vayan más rápido: muchos programas usan solo uno o pocos hilos, y si no están hechos para ejecutarse en paralelo, la mayoría de los núcleos quedan sin usar.",
  pts:["Núcleos físicos: unidades reales de procesamiento.","Hilos: unidades lógicas que el sistema operativo planifica.","Con Hyper-Threading, cada núcleo físico maneja dos hilos, pero comparten algunos recursos.","Factores que limitan el rendimiento: aplicaciones de un solo hilo, poca RAM que obliga a usar el archivo de paginación, y que el kernel debe organizar todos los hilos.","El kernel crea, planifica y termina procesos e hilos, y decide cuál recibe el procesador y por cuánto tiempo con un algoritmo de planificación.","Con demasiados procesos e hilos compitiendo, el sistema gasta mucho tiempo cambiando de uno a otro: el cambio de contexto reduce el trabajo útil y produce interrupciones y tiempos de respuesta altos."],
  ojo:"Si el software no crea suficiente trabajo en paralelo, los núcleos e hilos extra no ayudan.",
  ex:"Navegador, editor de imágenes, reproductor y base de datos a la vez: el kernel reparte el tiempo de CPU entre sus procesos e hilos; si son demasiados, el usuario nota lentitud.",
  cards:[["Núcleos físicos vs hilos","Núcleos: unidades reales de procesamiento. Hilos: unidades lógicas que planifica el SO."],["Hyper-Threading","Cada núcleo físico maneja dos hilos, compartiendo algunos recursos."],["¿Por qué un multinúcleo no siempre acelera?","Muchos programas usan uno o pocos hilos y no aprovechan los demás núcleos."],["Costo de demasiados procesos e hilos","El cambio de contexto reduce el tiempo útil y sube los tiempos de respuesta."]]},
 {id:"ram",u:2,a:"P",src:SRC.p2,t:"Saturación de RAM y generaciones DDR",
  sum:"Con 8 GB de RAM y programas pesados abiertos, la memoria se llena rápido y el SO mueve páginas poco usadas al archivo de paginación en el disco. Las generaciones DDR usan voltajes, pines y velocidades diferentes, y la placa base debe soportar la generación.",
  pts:["El disco es mucho más lento que la RAM: el equipo se pone lento y se bloquea al cambiar de aplicación.","Mejoras: cerrar aplicaciones y pestañas sin uso, aumentar la RAM si la placa lo permite y tener el archivo de paginación en un SSD.","Visto en clase: DDR3 alrededor de 1066–1333 MHz (común con Intel Core i3, i5 e i7).","DDR4: de 2666 a 3200 MHz.","DDR5: de 4800 a 8600 MT/s, con procesadores modernos de Apple, Intel Core i9 y AMD.","Reemplazar todas las memorias por DDR5 no siempre es viable: DDR5 en una placa hecha para DDR4 no funciona.","Antes de actualizar: revisar en el manual de la placa la generación y velocidad máxima, el procesador, el número de ranuras y la capacidad máxima."],
  ojo:"El bus de transferencia y la generación de la RAM también influyen en qué tan rápido se mueven los datos entre el procesador y la memoria.",
  ex:"Un diseñador con 8 GB que usa modelado 3D, edición de video, navegador y oficina sufre bloqueos al cambiar de aplicación.",
  cards:[["Velocidades DDR vistas en clase","DDR3: 1066–1333 MHz. DDR4: 2666–3200 MHz. DDR5: 4800–8600 MT/s."],["¿Se puede poner DDR5 en una placa DDR4?","No: la placa debe soportar esa generación."],["Mejoras ante RAM saturada","Cerrar apps y pestañas sin uso, más RAM si la placa lo permite y paginación en SSD."]]},
 {id:"buses",u:2,a:"P",src:SRC.p2,t:"Buses de transferencia y MT/s",
  sum:"Los buses de transferencia son los caminos por donde se mueven los datos entre el procesador, la memoria RAM y otros componentes. Su velocidad determina qué tan rápido se envía y recibe la información.",
  pts:["MT/s (megatransferencias por segundo): cuántas transferencias de datos puede hacer el bus por segundo.","Un valor de MT/s más alto generalmente significa mayor ancho de banda.","Aunque el procesador sea moderno y haya 32 GB de RAM, un bus limitado (una generación DDR antigua o un cuello de botella en el controlador de memoria) hace lenta la transferencia de grandes cantidades de datos.","Qué revisar: la generación de la memoria, la frecuencia o MT/s que realmente soportan la placa y el procesador, y si la memoria trabaja en dual channel.","Cada generación DDR tiene una tasa de transferencia asociada a familias de procesadores específicas."],
  ojo:"El bus de transferencia de la memoria debe coincidir con lo que el procesador y la placa pueden manejar.",
  ex:"Un equipo con mucha RAM puede seguir lento al mover grandes volúmenes de datos si la memoria no trabaja en dual channel.",
  cards:[["¿Qué es un bus de transferencia?","El camino por donde se mueven los datos entre el procesador, la RAM y otros componentes."],["¿Qué significa MT/s?","Megatransferencias por segundo: cuántas transferencias hace el bus cada segundo."],["MT/s y ancho de banda","Un valor más alto generalmente significa mayor ancho de banda."]]},
 {id:"gpu",u:2,a:"P",src:SRC.p2,t:"Chip gráfico, gráficos integrados, dedicados y VRAM",
  sum:"Un chip gráfico (GPU) es el componente que procesa la información visual. Los gráficos integrados vienen dentro del procesador y comparten la RAM del sistema; una tarjeta de video dedicada tiene su propio procesador y su propia memoria VRAM.",
  pts:["Integrados: más económicos y de menor consumo; suficientes para oficina, pero reducen la RAM disponible y rinden menos en modelado 3D y diseño.","Dedicada: no compite con el sistema por la memoria y maneja cargas gráficas más pesadas.","Se necesita una GPU dedicada para renderizado 3D continuo o edición de video con efectos.","Procesador potente y gráficos débiles: la CPU se encarga de las tareas generales y la GPU del renderizado; con una GPU débil, las aplicaciones visuales van mal aunque la CPU sea potente.","Con gráficos integrados, parte de la RAM se reserva para la GPU: con 16 GB, a las aplicaciones les queda menos.","Una tarjeta con 8 GB de VRAM guarda los datos gráficos en su propia memoria y deja libres los 16 GB del sistema.","La VRAM es más rápida y está optimizada para gráficos; evita el cuello de botella de compartir el bus de la memoria del sistema."],
  ojo:"Un procesador de 16 núcleos y 32 hilos es muy bueno para cálculos en paralelo, pero el rendimiento gráfico depende principalmente de la GPU.",
  ex:"Edición de video, renderizado y modelado 3D manejan texturas y frames grandes que deben accederse rápido: ahí la VRAM dedicada marca la diferencia.",
  cards:[["¿Qué es un chip gráfico (GPU)?","El componente que procesa la información visual."],["Integrados vs dedicados","Integrados: dentro del procesador, comparten la RAM. Dedicados: procesador y VRAM propios."],["CPU vs GPU","CPU: tareas generales. GPU: renderizado. Con una GPU débil, lo visual va mal aunque la CPU sea potente."],["Ventaja de la VRAM","Es más rápida, está optimizada para gráficos y deja libre la RAM del sistema."]]},
 {id:"compat",u:2,a:"P",src:SRC.p2,t:"Compatibilidad entre componentes de hardware",
  sum:"Antes de actualizar procesadores, memorias o tarjetas gráficas hay que verificar que todos los componentes sean compatibles entre sí.",
  pts:["Placa base: debe soportar el nuevo procesador (socket y chipset).","Memoria: la placa debe soportar la generación (DDR4 o DDR5).","Tarjeta gráfica: ranura PCIe y conectores de poder.","Fuente de poder: capacidad suficiente y conectores correctos para la nueva GPU.","Refrigeración: debe poder manejar el mayor calor de los procesadores y tarjetas modernas.","Estrategia segura: 1) revisar las especificaciones de la placa; 2) elegir componentes compatibles; 3) confirmar que la fuente y la refrigeración del case sean adecuadas."],
  ojo:"Actualizar todo al mismo tiempo sin revisar la compatibilidad puede dañar componentes o dejar un equipo que no enciende.",
  ex:"Una empresa quiere procesadores modernos, DDR5 y tarjetas dedicadas, pero tiene placas antiguas, fuentes de baja capacidad y refrigeración básica.",
  cards:[["¿Qué se revisa en la placa base?","Socket y chipset del procesador, generación de RAM y ranura PCIe."],["¿Qué se revisa en la fuente de poder?","Capacidad suficiente y conectores correctos para la GPU."],["Orden de la estrategia de actualización","Especificaciones de la placa → componentes compatibles → fuente y refrigeración."]]},
 {id:"integral",u:2,a:"P",src:SRC.p2,t:"Diagnóstico integral de un computador",
  sum:"Equipo evaluado: procesador de 4 núcleos y 8 hilos, 8 GB de RAM DDR4, gráficos integrados con memoria compartida y SSD de 256 GB, usado para diseño gráfico, edición de video y ofimática.",
  pts:["Componentes que limitan: los 8 GB de RAM (muy poca para diseño y video), los gráficos integrados que comparten la memoria y el procesador de 4 núcleos y 8 hilos, que puede quedarse corto en tareas pesadas en paralelo.","Relación: los hilos del procesador necesitan RAM para trabajar bien, y los gráficos integrados reducen aún más la RAM disponible; con varias aplicaciones, el sistema pagina y baja el rendimiento gráfico.","Primera prioridad: la RAM (mínimo 16 GB o 32 GB de DDR4 compatible), porque reduce de inmediato la paginación.","Segunda prioridad: una tarjeta gráfica dedicada, para que el video y el 3D no compartan la memoria del sistema.","Cambiar el procesador casi siempre exige una placa nueva y sale más caro.","Configuración recomendada: mantener o mejorar el procesador si es posible, 32 GB de DDR4, GPU dedicada con al menos 6–8 GB de VRAM y el SSD actual (o uno más grande)."],
  ojo:"El orden importa: primero la RAM, después la GPU dedicada, y el procesador solo si es posible.",
  ex:"Síntomas reportados: lentitud con varias aplicaciones, dificultad para procesar videos y bloqueos ocasionales.",
  cards:[["¿Qué actualizar primero en el equipo evaluado?","La RAM (16 o 32 GB DDR4 compatible), porque reduce la paginación de inmediato."],["Segunda prioridad","Una tarjeta gráfica dedicada."],["¿Por qué no cambiar el procesador primero?","Casi siempre exige una placa nueva y sale más caro."],["Configuración recomendada","CPU actual o mejor, 32 GB DDR4, GPU de 6–8 GB de VRAM y el SSD actual o uno más grande."]]},

 /* ================= UNIDAD 3 · TEORÍA ================= */
 {id:"dist1",u:3,a:"T",src:SRC.t3,t:"Concepto de sistemas distribuidos",
  sum:"Un sistema distribuido es una colección de computadores conectados por una red que coordinan sus acciones y aparecen ante el usuario como un único sistema coherente. Cada nodo tiene su propia CPU, memoria y almacenamiento, y cooperan mandándose mensajes.",
  pts:["Procesamiento: el distribuido divide la carga entre varios nodos; el centralizado ejecuta todo en un servidor.","Administración de recursos: compartida entre nodos, en vez de controlada desde un solo punto.","Comunicación: por mensajes en la red, en vez de llamadas locales.","Gracias a esto, el sistema sigue funcionando aunque falle un nodo, algo imposible si todo depende de un único computador."],
  ojo:"El taller pide comparar con el sistema centralizado en tres aspectos: procesamiento, administración de recursos y comunicación.",
  ex:"En un sistema centralizado, si el único servidor cae, todos pierden el servicio.",
  cards:[["¿Qué es un sistema distribuido?","Computadores conectados por red que coordinan sus acciones y se ven como un único sistema."],["Distribuido vs centralizado","Carga repartida vs un solo servidor; recursos compartidos vs un punto de control; mensajes en red vs llamadas locales."]]},
 {id:"dist2",u:3,a:"T",src:SRC.t3,t:"Arquitectura cliente-servidor",
  sum:"Para la plataforma académica de una universidad conviene una arquitectura cliente-servidor de tres niveles: el cliente, el servidor de aplicaciones y la base de datos.",
  pts:["Cliente (navegador o app móvil): presentación visual y envío de las peticiones.","Servidor de aplicaciones: recibe las peticiones, aplica la lógica del negocio (por ejemplo, valida notas y fechas de entrega) y coordina las operaciones.","Base de datos: guarda y devuelve los datos de forma persistente, como notas y trabajos.","Estudiantes y docentes solo interactúan con el cliente; el servidor de aplicaciones protege la base de datos y hace las validaciones.","La separación hace el sistema más sencillo de mantener y escalar: se pueden agregar validaciones en el servidor sin cambiar el cliente ni la base de datos."],
  ojo:"Validar notas y fechas es lógica de negocio: le corresponde al servidor de aplicaciones.",
  ex:"El estudiante ve sus notas en el navegador; el servidor de aplicaciones las consulta en la base de datos y se las devuelve.",
  cards:[["Los tres niveles","Cliente (presentación), servidor de aplicaciones (lógica del negocio) y base de datos (datos persistentes)."],["¿Quién valida notas y fechas?","El servidor de aplicaciones."]]},
 {id:"dist3",u:3,a:"T",src:SRC.t3,t:"Comunicación entre procesos (IPC)",
  sum:"La comunicación entre procesos es esencial porque los procesos que corren en distintos computadores necesitan intercambiar datos y coordinar su trabajo. Sin ella, los nodos no pueden funcionar como uno solo.",
  pts:["Sockets: identificados por la dirección IP y el puerto.","Paso de mensajes.","Colas de mensajes: desacoplan a quien envía de quien recibe; un proceso envía el mensaje y sigue trabajando aunque el otro esté ocupado.","Para un intercambio confiable se usan protocolos con confirmaciones y reintentos, así la información no se pierde si falla la red."],
  ojo:"La ventaja clave de la cola de mensajes es que el emisor no tiene que esperar al receptor.",
  ex:"Al registrar una venta, el proceso de ventas deja un mensaje en la cola del inventario hasta que el servicio de inventario lo procesa.",
  cards:[["Socket","Mecanismo de comunicación identificado por la dirección IP y el puerto."],["Ventaja de la cola de mensajes","El emisor sigue trabajando aunque el receptor esté ocupado."],["¿Cómo se evita perder mensajes?","Con protocolos de confirmaciones y reintentos."]]},
 {id:"dist4",u:3,a:"T",src:SRC.t3,t:"Comunicación síncrona y asíncrona",
  sum:"En la comunicación síncrona, el emisor espera la respuesta antes de continuar. En la asíncrona, el emisor sigue trabajando y recibe la respuesta después.",
  pts:["Síncrona: cuando se necesita respuesta inmediata, como validar un pago o revisar si un asiento de cine está disponible antes de confirmar la compra.","Asíncrona: para tareas que pueden procesarse en segundo plano, como enviar notificaciones o actualizar estadísticas.","En la universidad: confirmar el registro del estudiante debe ser síncrono; enviar un correo puede ser asíncrono.","Elegir bien el modelo mejora la velocidad y evita bloquear procesos innecesariamente."],
  ojo:"Pregunta típica: si el usuario necesita saber el resultado en el momento, síncrona; si se puede terminar después, asíncrona.",
  ex:"Comprar una boleta de cine: verificar el asiento es síncrono; enviar el correo con la boleta es asíncrono.",
  cards:[["Comunicación síncrona","El emisor espera la respuesta antes de continuar."],["Comunicación asíncrona","El emisor sigue trabajando y recibe la respuesta después."],["Ejemplos de cada una","Síncrona: validar un pago. Asíncrona: enviar notificaciones o un correo."]]},
 {id:"dist5",u:3,a:"T",src:SRC.t3,t:"Transparencia en sistemas distribuidos",
  sum:"La transparencia permite a los usuarios acceder a recursos ubicados en diferentes servidores sin conocer su ubicación física ni qué máquina procesa la petición.",
  pts:["Ejemplo: un estudiante abre un documento compartido o ve sus notas sin saber en qué servidor están.","Dificultad 1: mantener actualizada la asignación de ubicaciones cuando se mueven o agregan servidores.","Dificultad 2: manejar las ralentizaciones de la red para que el usuario no las note.","Dificultad 3: mantener ocultos los fallos para que el usuario siga recibiendo respuestas correctas.","Una transparencia total requiere capas de software que gestionen la asignación de nombres, la replicación y la recuperación."],
  ojo:"El taller pide las dos partes: cómo funciona la transparencia y qué dificultades técnicas tiene.",
  ex:"Si la base de datos de notas se mueve a otro servidor, el estudiante sigue entrando igual.",
  cards:[["¿Qué es la transparencia?","Acceder a recursos en distintos servidores sin conocer su ubicación física."],["Tres dificultades de la transparencia","Mantener las ubicaciones actualizadas, ocultar la lentitud de la red y ocultar los fallos."]]},
 {id:"dist6",u:3,a:"T",src:SRC.t3,t:"Tolerancia a fallos",
  sum:"Si un servidor de una empresa financiera falla durante una transacción, el sistema debe seguir operando y proteger la integridad de los datos.",
  pts:["Redundancia: servidores de respaldo listos para tomar el control.","Copia de datos (replicación): copias de la base de datos en varios nodos.","Conmutación por error automática: transferir el control al respaldo de forma inmediata.","Protocolos de confirmación en las transacciones: o se aplican todos los cambios o ninguno, evitando actualizaciones parciales.","Copias de seguridad regulares: permiten restablecer el último estado consistente después de un daño mayor."],
  ojo:"El peligro en una transacción interrumpida es la actualización parcial; por eso se usan protocolos de confirmación.",
  ex:"Con estos mecanismos, el servicio sigue disponible y los datos financieros siguen correctos aunque falle un componente.",
  cards:[["Mecanismos de tolerancia a fallos","Redundancia, replicación, conmutación por error automática, protocolos de confirmación y copias de seguridad."],["¿Qué evitan los protocolos de confirmación?","Las actualizaciones parciales: se aplican todos los cambios o ninguno."]]},
 {id:"dist7",u:3,a:"T",src:SRC.t3,t:"Escalabilidad y disponibilidad",
  sum:"Si una plataforma universitaria se satura en matrículas, se mejora con balanceadores de carga, más servidores y una base de datos replicada.",
  pts:["Balanceador de carga: reparte las peticiones entre varios servidores de aplicación; si uno se cae, los otros siguen atendiendo.","Agregar más servidores a medida que crecen los usuarios, en vez de solo mejorar uno.","Ampliar recursos: más servidores de aplicación y una base de datos replicada.","Así, en el pico de matrículas el sistema no se pone lento ni se cae y sigue disponible."],
  ojo:"El taller pide justificar tres cosas: balanceadores de carga, redundancia y ampliación de recursos.",
  ex:"Miles de estudiantes entran a matricularse a la misma hora y el balanceador reparte las peticiones entre varios servidores.",
  cards:[["¿Qué hace un balanceador de carga?","Reparte las peticiones entre varios servidores; si uno cae, los demás siguen atendiendo."],["Estrategia ante la saturación en matrículas","Balanceador, más servidores de aplicación y base de datos replicada."]]},
 {id:"dist8",u:3,a:"T",src:SRC.t3,t:"Sistemas de archivos distribuidos",
  sum:"Para una organización con cuatro sedes, los archivos se replican en varios servidores y el usuario accede a ellos sin saber en cuál están.",
  pts:["Disponibilidad: si un servidor se cae, se accede desde otra copia.","Control de acceso: quién puede ver o cambiar cada documento según su cargo.","Consistencia: bloqueos o versiones cuando dos personas modifican lo mismo a la vez.","Seguridad: copias de seguridad y cifrado para que la información no se pierda ni la vea quien no debe."],
  ojo:"Las cuatro garantías del taller: disponibilidad, seguridad, control de acceso y consistencia.",
  ex:"Un documento editado en una sede se puede abrir desde cualquiera de las otras.",
  cards:[["Cuatro garantías del sistema de archivos distribuido","Disponibilidad, seguridad, control de acceso y consistencia."],["¿Cómo se mantiene la consistencia?","Con bloqueos o versiones cuando dos personas modifican lo mismo."]]},
 {id:"dist9",u:3,a:"T",src:SRC.t3,t:"Aplicaciones empresariales de los sistemas distribuidos",
  sum:"Una empresa de retail con varias tiendas y venta por internet puede distribuir el inventario, los pedidos, los datos de clientes y los pagos.",
  pts:["Cada tienda o nodo comparte la información de inventario y clientes por medio de una base de datos común.","Cuando alguien compra en una ciudad, se actualiza el stock para las demás.","Comunicación síncrona para operaciones críticas, como confirmar si hay stock antes de vender.","Comunicación asíncrona para notificaciones o reportes, sin detener el proceso.","Beneficios: si se cae un servidor, las tiendas siguen vendiendo, y es más fácil abrir nuevas tiendas sin rehacer el sistema."],
  ojo:"El taller pide identificar servicios distribuidos, recursos compartidos, mecanismos de comunicación y beneficios.",
  ex:"Una venta en línea descuenta el stock y la tienda física de otra ciudad lo ve actualizado.",
  cards:[["Servicios que distribuye la empresa de retail","Inventario, pedidos, datos de clientes y pagos."],["Beneficios de distribuir","Disponibilidad si cae un servidor y crecimiento sin rehacer el sistema."]]},

 /* ================= UNIDAD 3 · PRÁCTICA ================= */
 {id:"ms1",u:3,a:"P",src:SRC.p3,t:"Caso MULTISERVICIOS: diagnóstico y arquitectura",
  sum:"MULTISERVICIOS S.A. tiene cuatro sedes, unos 350 empleados y un sistema centralizado en un único servidor que maneja inventario, facturación, ventas, clientes y documentos.",
  pts:["Problemas: saturación del servidor, interrupción de servicios cuando falla, inventario que no se refleja a tiempo en otras sedes, duplicidad de información, almacenamiento sin replicación, falta de control de accesos por cargo y crecimiento a tres sedes nuevas.","El modelo centralizado se queda corto: se satura, si cae todas las sedes pierden acceso y no replica los documentos.","Nueva arquitectura: varios nodos que reparten el trabajo, replican los datos importantes y siguen funcionando aunque uno caiga, con un servicio unificado para los usuarios.","Cliente-servidor de tres niveles: clientes en cada sede (computadores o aplicaciones web), servidores de aplicaciones con las reglas del negocio y servidores de bases de datos replicados entre sedes.","Los clientes solo hablan con los servidores de aplicaciones; los balanceadores de carga reparten las peticiones, y para las sedes nuevas se agregan servidores sin cambiar los clientes."],
  ojo:"El taller pide aplicar los componentes teóricos al caso: relaciona cada problema con el componente que lo resuelve.",
  ex:"Al abrir una sede nueva, se agregan servidores de aplicaciones y la base de datos replicada, sin tocar las aplicaciones de los clientes.",
  cards:[["¿Por qué falla el modelo centralizado del caso?","Se satura, si el servidor cae todas las sedes pierden acceso y no hay replicación de documentos."],["Arquitectura propuesta","Cliente-servidor de tres niveles con balanceadores y bases de datos replicadas entre sedes."]]},
 {id:"ms2",u:3,a:"P",src:SRC.p3,t:"Caso MULTISERVICIOS: comunicación, fallos y archivos",
  sum:"La solución distribuida define cómo se comunican los procesos entre sedes, qué modelo usar en cada proceso, cómo mantener el servicio ante fallos y cómo compartir documentos entre las siete sedes.",
  pts:["Comunicación: paso de mensajes y colas de mensajes; la venta deja un mensaje en la cola del inventario hasta que se procesa. Sockets para comunicación directa con respuesta inmediata. Confirmaciones y reintentos para no perder mensajes.","Facturación y confirmación de pagos: síncrona, para que el empleado sepa de inmediato que la factura quedó registrada.","Actualización de inventario entre sedes: asíncrona; la sede registra la venta y sigue trabajando.","Notificaciones (alertas de stock bajo, reportes diarios): asíncronas, con publicación-suscripción.","Tolerancia a fallos: datos críticos copiados en al menos dos servidores de sedes diferentes, respaldo que toma el control automáticamente, copias de seguridad regulares, procedimiento de recuperación y balanceadores que alejan el tráfico del nodo caído.","Documentos: almacenamiento distribuido con replicación, una sola interfaz, control de acceso basado en roles, bloqueos o versiones, cifrado y copias de seguridad."],
  ojo:"El sistema de archivos debe servir a siete sedes: las cuatro actuales y las tres nuevas.",
  ex:"Si la red entre ciudades falla un momento, el mensaje de la venta espera en la cola y no se pierde.",
  cards:[["Modelo para la facturación","Síncrono: confirmación inmediata de que la factura quedó registrada."],["Modelo para inventario y notificaciones","Asíncrono; las notificaciones con publicación-suscripción."],["Datos críticos ante fallos","Copiados en al menos dos servidores de sedes diferentes."],["Control de acceso a documentos","Basado en roles, según el cargo de cada empleado."]]},

 /* ================= UNIDAD 4 · TEORÍA ================= */
 {id:"boot1",u:4,a:"T",src:SRC.b4+" · "+SRC.lb,t:"Proceso de arranque, UEFI y gestor de arranque",
  sum:"El booteo es el proceso de arranque del computador hasta que el sistema operativo inicia. En el proyecto, la cadena fue: el firmware UEFI inicia el hardware, lanza una entrada EFI, GRUB muestra el menú y se monta la partición raíz para que arranque Lubuntu.",
  pts:["UEFI: el firmware inicializa el hardware y arranca una entrada de arranque EFI.","Partición EFI: guarda los archivos de arranque que el firmware puede lanzar.","Gestor de arranque (GRUB, GNU GRand Unified Bootloader): muestra el menú de sistemas y arranca el que se elija.","Partición raíz (/): se monta y desde ella inicia Lubuntu.","En el arranque dual, GRUB mostró Lubuntu y Windows Boot Manager, y los dos arrancaron.","Preguntas de inmersión del taller: qué es el booteo, BIOS vs UEFI, función del gestor de arranque, qué es una imagen ISO, GPT vs MBR y qué es una máquina virtual."],
  ojo:"El orden de la cadena es la pregunta clave: UEFI → entrada EFI → GRUB → partición raíz → sistema operativo.",
  ex:"Al encender la Lenovo, GRUB permite elegir entre Lubuntu y Windows.",
  cards:[["Cadena de arranque del proyecto","UEFI → entrada EFI → GRUB → partición raíz (/) → Lubuntu."],["Función del gestor de arranque","Mostrar el menú de sistemas operativos y arrancar el elegido."],["¿Qué guarda la partición EFI?","Los archivos de arranque que el firmware UEFI puede lanzar."]]},
 {id:"boot2",u:4,a:"T",src:SRC.b4+" · "+SRC.lb,t:"Imagen ISO, medio booteable, GPT/MBR y máquinas virtuales",
  sum:"Para instalar se descarga la imagen ISO del sistema y se graba en un USB booteable con Rufus o Ventoy. El esquema del USB debe corresponder al modo de arranque del equipo.",
  pts:["Materiales del taller: computador, VirtualBox o VMware, memoria USB de mínimo 8 GB (16 GB recomendable), imagen ISO de Ubuntu Desktop, Linux o Windows, Rufus o Ventoy y software para grabar video.","En el proyecto, Rufus grabó la ISO de Lubuntu en el USB.","El USB se preparó con GPT para arranque UEFI, no para BIOS antiguo (legacy) ni CSM.","El taller pide registrar la herramienta usada, el tiempo, el sistema de particiones elegido y la diferencia entre GPT y MBR.","La instalación puede hacerse en una máquina virtual o en un equipo físico autorizado; se registran el sistema, la RAM, el disco, los procesadores asignados y el nombre del equipo."],
  ojo:"Si el USB no aparece al arrancar, hay que confirmar la configuración GPT/UEFI.",
  ex:"Antes de instalar, el USB de Lubuntu arrancó en una sesión en vivo para probar el Wi-Fi y el audio.",
  cards:[["Herramientas para crear el USB booteable","Rufus o Ventoy."],["Esquema elegido para un equipo UEFI","GPT para arranque UEFI, no BIOS antiguo ni CSM."],["Datos a registrar en la instalación","Sistema operativo, RAM, disco, procesadores asignados y nombre del equipo."]]},

 /* ================= UNIDAD 4 · PRÁCTICA ================= */
 {id:"inst",u:4,a:"P",src:SRC.b4,t:"Taller de booteo: actividades, evidencias y verificación",
  sum:"El taller se divide en cinco partes: preparación del medio booteable, configuración del arranque, instalación, verificación y video.",
  pts:["Parte I: descargar la ISO (registrar sistema, versión y tamaño) y crear el USB con Rufus o Ventoy.","Parte II: inspeccionar el BIOS/UEFI (fabricante, versión, tipo de arranque, Secure Boot y fecha) y configurar el equipo para iniciar desde el USB.","Parte III: instalar con siete evidencias: inicio del instalador, idioma, particiones, usuario, instalación en progreso, primer inicio y escritorio final.","Parte IV: verificación en Linux con uname -a, hostnamectl y lsblk; en Windows con systeminfo desde cmd. Se adjuntan capturas.","Parte V: video de 5 a 10 minutos en MP4 a 720p mínimo, con narración propia, o un enlace de Drive o YouTube.","Cierre: análisis y reflexión, y mínimo cinco conclusiones técnicas en el PDF."],
  ojo:"El taller vale el 25 % de la nota del ciclo y dura 4 horas.",
  ex:"Contenido del video: introducción, sistema elegido, objetivo, descarga de la ISO, creación del USB, configuración BIOS/UEFI, selección del dispositivo de arranque, instalación, configuración inicial, verificación y conclusiones.",
  cards:[["Comandos de verificación en Linux","uname -a, hostnamectl y lsblk."],["Comando de verificación en Windows","systeminfo, desde la consola cmd."],["Datos de la inspección BIOS/UEFI","Fabricante, versión, tipo de arranque, Secure Boot y fecha."],["Duración y formato del video","De 5 a 10 minutos, MP4 a 720p mínimo, con narración propia (o enlace de Drive o YouTube)."]]},
 {id:"lub",u:4,a:"P",src:SRC.lb,t:"Proyecto: Lubuntu en arranque dual",
  sum:"Se instaló Lubuntu junto a Windows en una Lenovo IdeaPad para aprender los fundamentos de Linux y usar el portátil como laboratorio en casa. Resultado: arranque dual funcionando desde GRUB, con Lubuntu actualizado y probado.",
  pts:["Equipo: Lenovo IdeaPad S145-14IWL (81MU), Intel Core i7-8565U de 4 núcleos y 8 hilos, 4 GB de RAM, Intel UHD Graphics 620 y NVIDIA GeForce MX110 de 2 GB, disco WD de 1 TB a 5400 RPM (SMR), Wi-Fi Qualcomm Atheros QCA9377 y UEFI Lenovo ASCN37WW (2019-07-04).","Sistema: Lubuntu 26.04.1 LTS con LXQt 2.3.2 (kernel registrado 7.0.0-43-generic); sistema original: Windows 10 Pro.","Restricción: el disco tiene fallas de lectura y sectores pendientes; no se le confían datos irremplazables.","Preparación: respaldo copiando (no moviendo) y verificando los archivos; D: se redujo en unos 102.400 MB para dejar unos 100 GB.","Particionado manual solo en el espacio liberado, sin formatear ni tocar las particiones NTFS de Windows.","sda7: 512 MiB, FAT32, montada en /boot/efi, con la marca EFI/boot. sda8: unos 99,5 GiB, ext4, montada en /.","Como F12 no abría bien el menú de Lenovo, se usó Inicio avanzado de Windows → Usar un dispositivo.","Después de instalar: sudo apt update y sudo apt upgrade; se probaron Wi-Fi, audio, navegador y YouTube, pantalla, teclado, touchpad, batería, suspensión y apagado.","Diagnóstico: se usó inxi y se instalaron htop, smartmontools, lm-sensors, sysstat e iotop."],
  ojo:"Dos particiones porque tienen propósitos y formatos distintos: la EFI es infraestructura de arranque y la raíz contiene el sistema de archivos de Linux. Linux podía compartir la EFI de Windows, pero se creó una aparte para mantenerlos separados.",
  ex:"Precaución del proyecto: las unidades pueden variar (MB y MiB, GB y GiB), así que se confirmaron tamaño, formato y punto de montaje antes de aplicar los cambios.",
  cards:[["Particiones de Lubuntu","sda7: 512 MiB FAT32 en /boot/efi. sda8: unos 99,5 GiB ext4 en /."],["¿Por qué copiar y no mover en el respaldo?","Porque el disco tiene errores de lectura: se copian y se verifican las copias."],["¿Cómo se arrancó desde el USB?","Inicio avanzado de Windows → Usar un dispositivo, porque F12 no abría bien el menú."],["¿Qué mostró GRUB al final?","Lubuntu y Windows Boot Manager; los dos arrancaron."]]}
];
TOPICS.forEach(t=>{if(!t.u)t.u=1});
