 {c:"ms",q:"¿Cuántas sedes y empleados tiene hoy MULTISERVICIOS?",o:["Cuatro sedes y unos 350 empleados","Siete sedes y 1000 empleados","Una sede y 50 empleados","Tres sedes y 100 empleados"],a:0,e:"Planea abrir tres sedes más."}
